const body = $input.first().json.body || {};
const action = body.action;
const projectId = body.project_id;
const params = body.params || {};

const validActions = [
  'pause', 'resume', 'retry', 'cancel', 'skip', 'force_complete',
  'change_state', 'update_config', 'reset', 'reprocess', 'get_status',
  'list_projects', 'force_delivery', 'run_review'
];

if (!action || !validActions.includes(action)) {
  return [{ json: { error: `Invalid action. Valid actions: ${validActions.join(', ')}`, valid_actions: validActions } }];
}

if (!projectId && !['list_projects'].includes(action)) {
  return [{ json: { error: 'project_id is required for this action' } }];
}

return [{
  json: {
    action: action,
    project_id: projectId,
    params: params,
    admin_id: body.admin_id || 'unknown',
    timestamp: new Date().toISOString()
  }
}];

const input = $input.first().json;
const action = input.action;

const actionMap = {
  'pause': { query: "UPDATE projects SET state = 'paused', updated_at = NOW() WHERE id = $1 RETURNING id, state", needsProject: true },
  'resume': { query: "UPDATE projects SET state = 'resumed', updated_at = NOW() WHERE id = $1 AND state = 'paused' RETURNING id, state", needsProject: true },
  'retry': { query: "UPDATE projects SET state = 'retrying', updated_at = NOW(), error_log = error_log || jsonb_build_object('retried_at', NOW()) WHERE id = $1 AND state IN ('failed', 'stuck') RETURNING id, state", needsProject: true },
  'cancel': { query: "UPDATE projects SET state = 'cancelled', updated_at = NOW(), state_history = state_history || jsonb_build_object('state', 'cancelled', 'at', NOW()) WHERE id = $1 RETURNING id, state", needsProject: true },
  'skip': { query: "UPDATE projects SET state = 'skipped', updated_at = NOW() WHERE id = $1 RETURNING id, state", needsProject: true },
  'force_complete': { query: "UPDATE projects SET state = 'completed', updated_at = NOW() WHERE id = $1 RETURNING id, state", needsProject: true },
  'change_state': { query: `UPDATE projects SET state = '${input.params.new_state || 'pending'}', updated_at = NOW() WHERE id = $1 RETURNING id, state`, needsProject: true },
  'reset': { query: "UPDATE projects SET state = 'pending', updated_at = NOW(), error_log = '{}'::jsonb WHERE id = $1 RETURNING id, state", needsProject: true },
  'get_status': { query: "SELECT id, title, state, overall_score, updated_at FROM projects WHERE id = $1", needsProject: true },
  'list_projects': { query: "SELECT id, title, state, overall_score, updated_at FROM projects ORDER BY updated_at DESC LIMIT 20", needsProject: false },
  'force_delivery': { query: "UPDATE projects SET state = 'approved', updated_at = NOW() WHERE id = $1 AND state = 'delivered' RETURNING id, state", needsProject: true },
  'run_review': { query: "UPDATE projects SET state = 'final_review', updated_at = NOW() WHERE id = $1 AND state IN ('rendered', 'animated') RETURNING id, state", needsProject: true }
};

const actionConfig = actionMap[action];

return [{
  json: {
    ...input,
    query: actionConfig.query,
    params: actionConfig.needsProject ? [input.project_id] : []
  }
}];

